package com.lambda.app.util

import android.media.AudioAttributes
import android.media.AudioFormat
import android.media.AudioManager
import android.media.AudioTrack
import android.media.ToneGenerator
import android.os.Handler
import android.os.Looper
import kotlin.math.abs
import kotlin.math.max
import kotlin.math.sin
import kotlin.random.Random

/** Short UI chimes (no sound files needed - generated by the system tone generator). */
object Chime {
    private val handler = Handler(Looper.getMainLooper())

    enum class Kind { Complete, Alert, Click }

    fun play(kind: Kind) {
        try {
            val tg = ToneGenerator(AudioManager.STREAM_MUSIC, 55)
            when (kind) {
                Kind.Click -> tg.startTone(ToneGenerator.TONE_PROP_BEEP, 60)
                Kind.Alert -> tg.startTone(ToneGenerator.TONE_PROP_ACK, 300)
                Kind.Complete -> {
                    tg.startTone(ToneGenerator.TONE_PROP_BEEP, 150)
                    handler.postDelayed({ runCatching { tg.startTone(ToneGenerator.TONE_PROP_BEEP2, 350) } }, 220)
                }
            }
            handler.postDelayed({ runCatching { tg.release() } }, 900)
        } catch (_: Exception) {
        }
    }
}

/** Synthesised focus noise (same idea as the web version: brown / pink / warm hum). 100% offline. */
object Ambient {
    const val OFF = "off"
    const val BROWN = "brown"
    const val PINK = "pink"
    const val WARM = "binaural"

    private var track: AudioTrack? = null

    fun play(type: String, volume: Float) {
        stop()
        if (type == OFF) return
        try {
            val sampleRate = 22050
            val n = sampleRate * 4
            val f = FloatArray(n)
            when (type) {
                BROWN -> {
                    var last = 0f
                    for (i in 0 until n) {
                        val white = Random.nextFloat() * 2f - 1f
                        last = (last + 0.02f * white) / 1.02f
                        f[i] = last * 3.5f
                    }
                }
                PINK -> {
                    var b0 = 0f; var b1 = 0f; var b2 = 0f; var b3 = 0f; var b4 = 0f; var b5 = 0f; var b6 = 0f
                    for (i in 0 until n) {
                        val white = Random.nextFloat() * 2f - 1f
                        b0 = 0.99886f * b0 + white * 0.0555179f
                        b1 = 0.99332f * b1 + white * 0.0750759f
                        b2 = 0.96900f * b2 + white * 0.1538520f
                        b3 = 0.86650f * b3 + white * 0.3104856f
                        b4 = 0.55000f * b4 + white * 0.5329522f
                        b5 = -0.7616f * b5 - white * 0.0168980f
                        f[i] = (b0 + b1 + b2 + b3 + b4 + b5 + b6 + white * 0.5362f) * 0.11f
                        b6 = white * 0.115926f
                    }
                }
                else -> { // warm hum
                    var last = 0f
                    for (i in 0 until n) {
                        val white = Random.nextFloat() * 2f - 1f
                        last = (last + 0.015f * white) / 1.015f
                        f[i] = last * 4f + 0.05f * sin(2.0 * Math.PI * 110.0 * i / sampleRate).toFloat()
                    }
                }
            }
            // gentle low-pass for smoothness
            val alpha = if (type == PINK) 0.55f else 0.12f
            var y = 0f
            for (i in 0 until n) { y += alpha * (f[i] - y); f[i] = y }
            // normalise
            var peak = 0.0001f
            for (v in f) peak = max(peak, abs(v))
            val data = ShortArray(n) { (f[it] / peak * 0.8f * Short.MAX_VALUE).toInt().toShort() }

            val t = AudioTrack.Builder()
                .setAudioAttributes(
                    AudioAttributes.Builder()
                        .setUsage(AudioAttributes.USAGE_MEDIA)
                        .setContentType(AudioAttributes.CONTENT_TYPE_MUSIC)
                        .build()
                )
                .setAudioFormat(
                    AudioFormat.Builder()
                        .setEncoding(AudioFormat.ENCODING_PCM_16BIT)
                        .setSampleRate(sampleRate)
                        .setChannelMask(AudioFormat.CHANNEL_OUT_MONO)
                        .build()
                )
                .setBufferSizeInBytes(n * 2)
                .setTransferMode(AudioTrack.MODE_STATIC)
                .build()
            t.write(data, 0, n)
            t.setLoopPoints(0, n, -1)
            t.setVolume(volume.coerceIn(0f, 1f))
            t.play()
            track = t
        } catch (_: Exception) {
            track = null
        }
    }

    fun setVolume(volume: Float) {
        runCatching { track?.setVolume(volume.coerceIn(0f, 1f)) }
    }

    fun stop() {
        runCatching {
            track?.stop()
            track?.release()
        }
        track = null
    }
}
